const https = require\('https'\);

function fetchJSON\(path\) {
  return new Promise\(\(resolve\) => {
    const url = `https://qquce.cn${path}`;
    https.get\(url, {headers: {
      'Accept': 'application/json',
      'User-Agent': 'Mozilla/5.0 \(iPhone; CPU iPhone OS 16_0 like Mac OS X\)'
    }}, \(res\) => {
      let data = '';
      res.on\('data', chunk => data += chunk\);
      res.on\('end', \(\) => {
        try { resolve\({status: res.statusCode, json: JSON.parse\(data\)}\); }
        catch\(e\) { resolve\({status: res.statusCode, text: data.substring\(0, 300\)}\); }
      }\);
    }\).on\('error', e => resolve\({error: e.message}\)\);
  }\);
}

async function main\(\) {
  // Try various API paths
  const paths = [
    '/api/quiz/mbti_stage',
    '/bootstrap/mbti_stage',
    '/bootstrap',
    '/api/quiz/mbti_stage/questions',
    '/api/quiz/mbti_stage/config',
    '/ui-config/mbti_stage',
    '/ui-config',
  ];

  for \(const p of paths\) {
    const r = await fetchJSON\(p\);
    if \(r.json\) {
      console.log\('✅', p, JSON.stringify\(r.json\).substring\(0, 500\)\);
    } else if \(r.text && !r.text.includes\('<!doctype'\)\) {
      console.log\('📄', p, r.text.substring\(0, 200\)\);
    } else if \(r.status === 404\) {
      console.log\('❌', p, '404'\);
    } else if \(r.status === 200 && \(r.text || ''\).includes\('<!doctype'\)\) {
      console.log\('🏠', p, 'SPA \(no API\)'\);
    } else {
      console.log\('❓', p, r.status\);
    }
  }
}

main\(\);
NODEEOF)
